func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve aprirsi senza errori"):
		return
	var player := find_by_name(main, "Player") as CharacterBody2D
	if not check("player", player != null, "Nella scena serve un CharacterBody2D chiamato Player"):
		return

	# Test 1: Coyote Time + Azzeramento timer
	player.position = Vector2(400, 464)
	await wait_physics_frames(2)
	player.position = Vector2(400, 400)
	await wait_physics_frames(2)
	await tap_action("jump")
	check("coyote_active", player.velocity.y < 0.0, "Il salto deve attivarsi dentro la finestra di Coyote Time (velocity.y è %.1f)" % player.velocity.y)

	var coyote_val = get_prop(player, "coyote_timer", 1.0)
	var buffer_val = get_prop(player, "jump_buffer_timer", 1.0)
	check("timer_coyote_zero", float(coyote_val) <= 0.0, "coyote_timer deve essere azzerato dopo il salto (valore attuale: %s)" % str(coyote_val))
	check("timer_buffer_zero", float(buffer_val) <= 0.0, "jump_buffer_timer deve essere azzerato dopo il salto (valore attuale: %s)" % str(buffer_val))

	# Test 2: Jump Buffer all'atterraggio
	player.position = Vector2(400, 300)
	player.velocity = Vector2(0, 150)
	await wait_physics_frames(2)
	await tap_action("jump")
	await wait_physics_frames(2)
	player.position = Vector2(400, 464)
	await wait_physics_frames(3)
	check("buffer_active", player.velocity.y < 0.0, "Il salto premuto in volo deve attivarsi appena si tocca terra (velocity.y è %.1f)" % player.velocity.y)
",
