    "contenuto": "extends CharacterBody2D

@export var jump_height: float = 128.0
@export var jump_time_to_peak: float = 0.4
@export var speed: float = 200.0
@export var max_fall_speed: float = 600.0

@export_group("Tolleranze Salto")
@export var coyote_time: float = 0.15
@export var jump_buffer_time: float = 0.15

@export_group("Accelerazione e Attrito")
@export var ground_acceleration: float = 1200.0
@export var air_acceleration: float = 400.0
@export var ground_friction: float = 1000.0

var gravity: float
var jump_velocity: float

var coyote_timer: float = 0.0
var jump_buffer_timer: float = 0.0


func _ready() -> void:
	recalculate_physics()


func recalculate_physics() -> void:
	gravity = (2.0 * jump_height) / (jump_time_to_peak * jump_time_to_peak)
	jump_velocity = -(2.0 * jump_height) / jump_time_to_peak


func _physics_process(delta: float) -> void:
	if not is_on_floor():
		velocity.y += gravity * delta
		if velocity.y > max_fall_speed:
			velocity.y = max_fall_speed

	if is_on_floor():
		coyote_timer = coyote_time
	else:
		coyote_timer -= delta

	if Input.is_action_just_pressed("jump"):
		jump_buffer_timer = jump_buffer_time
	else:
		jump_buffer_timer -= delta

	if jump_buffer_timer > 0.0 and coyote_timer > 0.0:
		velocity.y = jump_velocity
		jump_buffer_timer = 0.0
		coyote_timer = 0.0

	if Input.is_action_just_released("jump") and velocity.y < 0.0:
		velocity.y *= 0.5

	var direction := Input.get_axis("move_left", "move_right")
	var accel := ground_acceleration if is_on_floor() else air_acceleration

	if direction != 0.0:
		velocity.x = move_toward(velocity.x, direction * speed, accel * delta)
	else:
		var decel := ground_friction if is_on_floor() else air_acceleration
		velocity.x = move_toward(velocity.x, 0.0, decel * delta)

	move_and_slide()
"
